/* global __dirname */
// Regenerate after changing the document, its shared modules, or the pinned Leaflet package.
// node src/features/maps/generateLeafletHtml.cjs [--check]
const { createHash } = require('node:crypto');
const { readFileSync, writeFileSync } = require('node:fs');
const { dirname, join } = require('node:path');
const ts = require('typescript');

const leaflet = dirname(require.resolve('leaflet/package.json'));
const dist = join(leaflet, 'dist');
const read = (path) => readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
const vendorScript = read(join(dist, 'leaflet.js')).replace(/^\/\/# sourceMappingURL=.*$/gm, '').trim();
const vendorCss = read(join(dist, 'leaflet.css')).replace(/url\((images\/[\w@.-]+\.png)\)/g, (_, path) =>
  `url(data:image/png;base64,${readFileSync(join(dist, path)).toString('base64')})`,
);
const license = read(join(leaflet, 'LICENSE'));

const dependencies = {
  '../../services/maps/laboratories': '../../services/maps/laboratories.ts',
  './mapProtocol': 'mapProtocol.ts',
  './leafletMap': 'leafletMap.ts',
  './nativeMapDocument': 'nativeMapDocument.ts',
};
const factories = Object.entries(dependencies).map(([id, path]) => {
  const source = read(join(__dirname, path));
  const { outputText } = ts.transpileModule(source, {
    compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2019 },
  });
  return `${JSON.stringify(id)}: function (exports, require) {\n${outputText}\n}`;
});
const bootstrap = `(function () {
const factories = {${factories.join(',\n')}};
const modules = new Map();
function require(id) {
  if (!modules.has(id)) {
    const exports = {};
    factories[id](exports, require);
    modules.set(id, exports);
  }
  return modules.get(id);
}
require('./nativeMapDocument').startNativeMap(window, document.getElementById('map'));
})();`;
const script = `${vendorScript}\n;${bootstrap}`.replace(/<\/script/gi, '<\\/script');
const hash = createHash('sha256').update(script).digest('base64');
const html = `<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'sha256-${hash}'; style-src 'unsafe-inline'; img-src https://tile.openstreetmap.org data:">
<style>
html, body { height: 100%; margin: 0; overflow: hidden; }
${vendorCss}
${read(join(__dirname, 'leafletMap.css'))}
</style>
</head>
<body>
<!-- ${license} -->
<div id="map" class="ppk-leaflet-map" data-instance="PPK_MAP_INSTANCE" data-preview="PPK_MAP_PREVIEW"></div>
<script>${script}</script>
</body>
</html>`;

const outputs = {
  'leafletHtml.generated.ts': `// Generated by generateLeafletHtml.cjs. Do not edit.\nexport default ${JSON.stringify(html)};\n`,
  'leafletVendor.generated.css': `/* Generated from Leaflet (BSD-2-Clause) by generateLeafletHtml.cjs. */\n${vendorCss}`,
};
for (const [name, content] of Object.entries(outputs)) {
  const path = join(__dirname, name);
  if (process.argv.includes('--check')) {
    if (read(path) !== content) {
      console.error(`${name} is stale. Run node src/features/maps/generateLeafletHtml.cjs`);
      process.exitCode = 1;
    }
  } else {
    writeFileSync(path, content);
  }
}
